print("Starting Simulation...")

for t in np.arange(0, ft, dt):
    
    # 1. Get Command & Environment
    r = compute_reference_trajectory(t, level='hard')
    # Pre-filter reference slightly to smooth steps
    r_filtered += dt * 4.0 * (r - r_filtered)
    
    if Config.TIME_VARYING_UNCERTAINTY:
        W_true_pitch, W_true_roll, W_true_yaw = compute_time_varying_uncertainty(t, x, level='hard')
        
    # indices for pitch (0,1), roll (2,3), yaw (4,5) inside x(6x1)

    # 2. Extract Axis States & Compute Regressors
    #    Note: Coupling terms (e.g. roll_dot * yaw_dot) come from physics
    pitch, dp = x[0,0], x[1,0]
    roll, dr = x[2,0], x[3,0]
    yaw, dy = x[4,0], x[5,0]
    
    theta_base_pitch = compute_basis(1.0, pitch, dp, dr*dy)
    theta_base_roll = compute_basis(1.0, roll, dr, dp*dy)
    theta_base_yaw = compute_basis(1.0, yaw, dy, dp*dr)
    
    # Extend regressor if using Lambda compensation
    if Config.INCLUDE_CONTROL_IN_REGRESSOR:
        theta_pitch = compute_extended_regressor(theta_base_pitch, un_prev[0], v_prev[0,0])
        theta_roll = compute_extended_regressor(theta_base_roll, un_prev[1], v_prev[1,0])
        theta_yaw  = compute_extended_regressor(theta_base_yaw, un_prev[2], v_prev[2,0])
    else:
        theta_pitch, theta_roll, theta_yaw = theta_base_pitch, theta_base_roll, theta_base_yaw

    # 3. Compute Adaptive Control (ua)
    if Config.ADAPTATION_ON:
        ua_pitch = -What_pitch.T @ theta_pitch
        ua_roll = -What_roll.T @ theta_roll
        ua_yaw = -What_yaw.T @ theta_yaw
        
        # Saturation
        if Config.USE_ADAPTIVE_SATURATION:
            ua_pitch = np.clip(ua_pitch, -MAX_ADAPTIVE_TORQUE['pitch'], MAX_ADAPTIVE_TORQUE['pitch'])
            ua_roll  = np.clip(ua_roll,  -MAX_ADAPTIVE_TORQUE['roll'],  MAX_ADAPTIVE_TORQUE['roll'])
            ua_yaw   = np.clip(ua_yaw,   -MAX_ADAPTIVE_TORQUE['yaw'],   MAX_ADAPTIVE_TORQUE['yaw'])
            
        ua = np.array([ua_pitch.item(), ua_roll.item(), ua_yaw.item()])
    else:
        ua = np.zeros(3)

    # 4. Performance Recovery (v)
    if Config.PERFORMANCE_RECOVERY_ON:
        e_state = x - xm
        
        # Simple first-order filter (scalar lam for all axes)
        lam = PerfRec.LAMBDA_SCALAR
        f += dt * (-lam * (f - e_state))
        g = lam * f + (Am - lam * np.eye(6)) @ e_state
        v_raw = np.linalg.pinv(B_full) @ g
        
        if PerfRec.USE_FILTERED:
            tau_v = PerfRec.tau_v_scalar
            v_filtered += dt * (v_raw - v_filtered) / tau_v
            v = v_filtered
        else:
            v = v_raw
    else:
        v = np.zeros((3,1))

    # 5. Nominal Control (un)
    #    u_nom = -K1*x + K2*r + v
    un_feedback = (-K1 @ x).flatten()
    un_feedforward = (K2 @ r_filtered).flatten()
    un = un_feedback + un_feedforward + v.flatten()

    # 6. Total Control Input
    u = un + ua
    
    # Rate Limiting
    if Config.USE_CONTROL_RATE_LIMITING:
        du = u - u_prev
        du_max = np.array([MAX_CONTROL_RATE['pitch'], MAX_CONTROL_RATE['roll'], MAX_CONTROL_RATE['yaw']]) * dt
        u = u_prev + np.clip(du, -du_max, du_max)
    u_prev = u.copy()
    
    # Store for next step (Algebraic loop prevention)
    un_prev = un.copy()
    v_prev = v.copy()

    # 7. Update System State (Integration)
    #    Real Physics: x_dot = A*x + B*Lambda*(u + Uncertainty)
    
    # Calculate true uncertainty torque (using base basis only)
    unc_pitch = (W_true_pitch.T @ theta_base_pitch).item()
    unc_roll = (W_true_roll.T @ theta_base_roll).item()
    unc_yaw = (W_true_yaw.T @ theta_base_yaw).item()
    unc_vec = np.array([[unc_pitch], [unc_roll], [unc_yaw]])

    x += dt * (A_full @ x + B_full @ Lambda_true @ (u.reshape(-1,1) + unc_vec))
    xm += dt * (Am @ xm + Bm @ r_filtered + (B_full @ v if Config.PERFORMANCE_RECOVERY_ON else 0))
    xr += dt * (Am @ xr + Bm @ r_filtered) # Pure reference model (no input aux)
    
    # Wrap ALL Angles (not just yaw) to prevent unbounded growth
    #x[0,0] = wrap_angle(x[0,0]); x[2,0] = wrap_angle(x[2,0]); x[4,0] = wrap_angle(x[4,0])
    #xm[0,0] = wrap_angle(xm[0,0]); xm[2,0] = wrap_angle(xm[2,0]); xm[4,0] = wrap_angle(xm[4,0])
    #xr[0,0] = wrap_angle(xr[0,0]); xr[2,0] = wrap_angle(xr[2,0]); xr[4,0] = wrap_angle(xr[4,0])

    # 8. Adaptive Law Update (Weights)
    if Config.ADAPTATION_ON:
        # Tracking Errors
        e_pitch_vec = np.array([[x[0,0] - xm[0,0]], [x[1,0] - xm[1,0]]])
        e_roll_vec  = np.array([[x[2,0] - xm[2,0]], [x[3,0] - xm[3,0]]])
        e_yaw_vec   = np.array([[x[4,0] - xm[4,0]], [x[5,0] - xm[5,0]]])
        
        # Deadzone Logic
        err_degs = [np.abs(e[0]*180/np.pi).item() for e in [e_pitch_vec, e_roll_vec, e_yaw_vec]]
        deadzones = []
        
        for i, axis in enumerate(['pitch', 'roll', 'yaw']):
            if Config.USE_ADAPTIVE_DEADZONE and err_degs[i] < DEADZONE_THRESHOLD:
                settled_time[axis] += dt
                deadzones.append(0.0)
            else:
                settled_time[axis] = 0.0
                deadzones.append(1.0)
        
        # Adaptation Gain Computation (Scheduling + Forgetting)
        gammas = {}
        for i, axis in enumerate(['pitch', 'roll', 'yaw']):
             g = get_scheduled_gamma(t, GAMMA_FINAL[axis], TAU_GAMMA) if Config.USE_GAMMA_SCHEDULING else GAMMA_FINAL[axis]
             if Config.USE_EXPONENTIAL_FORGETTING:
                 g *= (MIN_GAMMA_RATIO + (1-MIN_GAMMA_RATIO) * np.exp(-settled_time[axis] / FORGETTING_TIME_CONSTANT))
             gammas[axis] = g

        # Update Laws (Pitch example shown, same for others)
        def update_weight(What, Whatf, theta, e_vec, gamma, sigma, deadzone):
            norm = (1 + theta.T @ theta).item() if Config.USE_WEIGHT_NORMALIZATION else 1.0
            grad = theta @ (e_vec.T @ P_single_axis @ B_single_axis) * deadzone
            
            if Config.USE_LOW_FREQUENCY_LEARNING:
                # L1-style: dW = Gamma * (grad - Sigma*(W - Wf))
                What += dt * gamma * (grad - sigma * (What - Whatf)) / norm
                Whatf += dt * GAM_F * (What - Whatf)
            else:
                # Standard e-mod: dW = Gamma * (grad - Sigma*W)
                What += dt * gamma * (grad - sigma * What) / norm
            return What, Whatf

        What_pitch, Whatf_pitch = update_weight(What_pitch, Whatf_pitch, theta_pitch, e_pitch_vec, gammas['pitch'], SIGMA['pitch'], deadzones[0])
        What_roll, Whatf_roll   = update_weight(What_roll,  Whatf_roll,  theta_roll,  e_roll_vec,  gammas['roll'],  SIGMA['roll'],  deadzones[1])
        What_yaw, Whatf_yaw     = update_weight(What_yaw,   Whatf_yaw,   theta_yaw,   e_yaw_vec,   gammas['yaw'],   SIGMA['yaw'],   deadzones[2])

    # 9. Logging
    log['t'].append(t)
    log['x'].append(x.flatten().copy())
    log['xm'].append(xm.flatten().copy())
    log['xr'].append(xr.flatten().copy())
    log['u'].append(u.flatten().copy())
    log['ua'].append(ua.flatten().copy())
    log['un'].append(un.flatten().copy())
    log['unc_true'].append(unc_vec.flatten().copy())
    log['e'].append((x - xm).flatten().copy())
    
    # Detailed logs
    log['What_pitch'].append(What_pitch.flatten().copy())
    log['What_roll'].append(What_roll.flatten().copy())
    log['What_yaw'].append(What_yaw.flatten().copy())
    log['theta_pitch'].append(theta_pitch.flatten().copy())
    log['theta_roll'].append(theta_roll.flatten().copy())
    log['theta_yaw'].append(theta_yaw.flatten().copy())
    log['v'].append(v.flatten().copy())

print("Simulation Completed! Processing data...")

# Convert logs to numpy arrays for plotting
for key in log:
    log[key] = np.array(log[key])

print(f"Data points recorded: {len(log['t'])}")
