axes_diag[2, 0].grid(True, alpha=0.3)

# Time-domain comparison: v vs un vs ua
axes_diag[2, 1].plot(t_rec[:n_samples], v_rec[:n_samples, 0], 'r-', linewidth=1.5, label='v (perf recovery)', alpha=0.8)
axes_diag[2, 1].plot(t_rec[:n_samples], un_rec[:n_samples, 0] - v_rec[:n_samples, 0], 'b-', linewidth=1.5, label='un - v (feedback+ff)', alpha=0.8)
axes_diag[2, 1].plot(t_rec[:n_samples], ua_pitch_rec[:n_samples], 'g-', linewidth=1.5, label='ua (adaptive)', alpha=0.8)
axes_diag[2, 1].set_xlabel('Time [s]')
axes_diag[2, 1].set_ylabel('Control Component')
axes_diag[2, 1].set_title('Control Signal Decomposition (Pitch)')
axes_diag[2, 1].legend()
axes_diag[2, 1].grid(True, alpha=0.3)

plt.tight_layout()
plt.show()

# =============================================================================
# PRINT FREQUENCY ANALYSIS SUMMARY
# =============================================================================
print("=" * 70)
print("FREQUENCY ANALYSIS SUMMARY")
print("=" * 70)
print(f"\n📊 Detected Oscillation Characteristics:")
print(f"   Dominant frequency:     {dominant_freq:.2f} Hz ({dominant_freq*2*np.pi:.2f} rad/s)")
print(f"   Oscillation period:     {dominant_period*1000:.1f} ms")
print(f"\n📊 Reference Model Bandwidth:")
print(f"   ωn = {wn:.2f} rad/s = {wn/(2*np.pi):.2f} Hz")
print(f"\n📊 Current Filter Setting:")
tau_v = 0.05  # Current tau_v used in simulation
print(f"   tau_v = {tau_v:.3f} s → cutoff = {1/(2*np.pi*tau_v):.2f} Hz")

# Recommendation logic
print(f"\n" + "=" * 70)
print("FILTER TUNING RECOMMENDATIONS")
print("=" * 70)

# The filter should:
# 1. Pass frequencies below reference model bandwidth (keep useful signal)
# 2. Attenuate frequencies at/above the oscillation frequency

if dominant_freq > 2 * wn/(2*np.pi):
    # Oscillations are well above ref model BW - can filter aggressively
    recommended_cutoff = 2 * wn/(2*np.pi)  # 2x reference model bandwidth
    recommended_tau = 1 / (2*np.pi*recommended_cutoff)
    print(f"\n✅ GOOD NEWS: Oscillation ({dominant_freq:.1f} Hz) >> Ref model BW ({wn/(2*np.pi):.2f} Hz)")
    print(f"   → Can filter aggressively without losing tracking performance")
    print(f"\n   RECOMMENDED: tau_v = {recommended_tau:.3f} s (cutoff = {recommended_cutoff:.1f} Hz)")
    print(f"   This will attenuate oscillations by {20*np.log10(1/np.sqrt(1+(dominant_freq/recommended_cutoff)**2)):.1f} dB")
else:
    # Oscillations are close to ref model BW - need compromise
    recommended_cutoff = (dominant_freq + wn/(2*np.pi)) / 2
    recommended_tau = 1 / (2*np.pi*recommended_cutoff)
    print(f"\n⚠️  WARNING: Oscillation ({dominant_freq:.1f} Hz) close to Ref model BW ({wn/(2*np.pi):.2f} Hz)")
    print(f"   → Filtering will affect tracking - need compromise")
    print(f"\n   RECOMMENDED: tau_v = {recommended_tau:.3f} s (cutoff = {recommended_cutoff:.1f} Hz)")

print(f"\n📋 Quick Reference - tau_v options:")
print(f"   {'tau_v':<10} {'Cutoff (Hz)':<15} {'Osc. Attenuation':<20} {'Phase lag @ ωn':<15}")
print("-" * 60)
for tau in [0.01, 0.02, 0.05, 0.1, 0.2]:
    fc = 1/(2*np.pi*tau)
    atten = 20*np.log10(1/np.sqrt(1+(dominant_freq*2*np.pi*tau)**2))
    phase_lag = np.arctan(wn*tau) * 180/np.pi
    print(f"   {tau:<10.3f} {fc:<15.1f} {atten:<20.1f} dB {phase_lag:<15.1f}°")

print("\n" + "=" * 70)

