# FIGURE 12: PERFORMANCE METRICS SUMMARY
# =============================================================================
fig12, axes12 = plt.subplots(2, 2, figsize=(14, 10))
fig12.suptitle('Performance Metrics Summary', fontsize=16, fontweight='bold')

# RMS Error over time (sliding window)
window_size = 500
pitch_rms = np.array([np.sqrt(np.mean(pitch_error_mag[max(0,i-window_size):i+1]**2)) 
                      for i in range(len(pitch_error_mag))])
roll_rms = np.array([np.sqrt(np.mean(roll_error_mag[max(0,i-window_size):i+1]**2)) 
                     for i in range(len(roll_error_mag))])
yaw_rms = np.array([np.sqrt(np.mean(yaw_error_mag[max(0,i-window_size):i+1]**2)) 
                    for i in range(len(yaw_error_mag))])

axes12[0, 0].plot(t_rec, pitch_rms, 'b-', linewidth=2, label='Pitch')
axes12[0, 0].plot(t_rec, roll_rms, 'g-', linewidth=2, label='Roll')
axes12[0, 0].plot(t_rec, yaw_rms, 'r-', linewidth=2, label='Yaw')
axes12[0, 0].set_xlabel('Time [s]', fontsize=11)
axes12[0, 0].set_ylabel('RMS Error', fontsize=11)
axes12[0, 0].set_title('Rolling RMS Error', fontsize=12)
axes12[0, 0].legend(loc='best')
axes12[0, 0].grid(True, alpha=0.3)

# Control effort
pitch_effort = np.cumsum(np.abs(u_rec[:, 0])) * dt
roll_effort = np.cumsum(np.abs(u_rec[:, 1])) * dt
yaw_effort = np.cumsum(np.abs(u_rec[:, 2])) * dt

axes12[0, 1].plot(t_rec, pitch_effort, 'b-', linewidth=2, label='Pitch')
axes12[0, 1].plot(t_rec, roll_effort, 'g-', linewidth=2, label='Roll')
axes12[0, 1].plot(t_rec, yaw_effort, 'r-', linewidth=2, label='Yaw')
axes12[0, 1].set_xlabel('Time [s]', fontsize=11)
axes12[0, 1].set_ylabel('Cumulative Control Effort', fontsize=11)
axes12[0, 1].set_title('Total Control Effort', fontsize=12)
axes12[0, 1].legend(loc='best')
axes12[0, 1].grid(True, alpha=0.3)

# Settling time analysis (time to reach 2% of steady state)
axes12[1, 0].plot(t_rec, np.abs(e_pitch_rec[:, 0]), 'b-', linewidth=2, label='Pitch')
axes12[1, 0].plot(t_rec, np.abs(e_roll_rec[:, 0]), 'g-', linewidth=2, label='Roll')
axes12[1, 0].plot(t_rec, np.abs(e_yaw_rec[:, 0]), 'r-', linewidth=2, label='Yaw')
