axes12[1, 1].plot(e_roll_rec[:, 0], e_roll_rec[:, 1], 'g-', linewidth=1.5, alpha=0.7, label='Roll')
axes12[1, 1].plot(e_yaw_rec[:, 0], e_yaw_rec[:, 1], 'r-', linewidth=1.5, alpha=0.7, label='Yaw')
